101	static int lan_panel_read_all(const char *path, char *buffer, size_t size,
102	                              size_t *length)
103	{
104	  int fd = open(path, O_RDONLY);
105	  size_t used = 0;
106	
107	  if (fd < 0)
108	    {
109	      return -errno;
110	    }
111	
112	  while (used < size)
113	    {
114	      ssize_t chunk = read(fd, buffer + used, size - used);
115	      if (chunk == 0)
116	        {
117	          break;
118	        }
119	      if (chunk < 0)
120	        {
121	          int ret = errno == EINTR ? 0 : -errno;
122	          if (ret < 0)
123	            {
124	              close(fd);
125	              return ret;
126	            }
127	          continue;
128	        }
129	      used += (size_t)chunk;
130	    }
131	
132	  close(fd);
133	  *length = used;
134	  return 0;
135	}
