24	/* HTTP 响应辅助函数 */
25	static int send_response(int fd, int status_code, const char *status_text,
26	                        const char *content_type, const char *body)
27	{
28	  char header[512];
29	  size_t body_len = body ? strlen(body) : 0;
30	
31	  snprintf(header, sizeof(header),
32	           "HTTP/1.1 %d %s\r\n"
33	           "Content-Type: %s\r\n"
34	           "Content-Length: %zu\r\n"
35	           "Connection: close\r\n"
36	           "\r\n",
37	           status_code, status_text, content_type, body_len);
38	
39	  if (write(fd, header, strlen(header)) < 0)
40	    {
41	      return -errno;
42	    }
43	
44	  if (body && body_len > 0)
45	    {
46	      if (write(fd, body, body_len) < 0)
47	        {
48	          return -errno;
49	        }
50	    }
51	
52	  return 0;
53	}
54	
55	static int send_json_error(int fd, int status_code, const char *message)
56	{
57	  char body[256];
58	  snprintf(body, sizeof(body), "{\"error\":\"%s\"}", message);
59	  return send_response(fd, status_code, "Error", "application/json", body);
60	}
