62	/* GET /api/v1/voice/config */
63	int voice_config_api_get(int client_fd)
64	{
65	  char buffer[ROUTINE_CONFIG_MAX_BYTES];
66	  cJSON *root = NULL;
67	  cJSON *voice_config = NULL;
68	  char *response_json = NULL;
69	  int fd = -1;
70	  ssize_t bytes_read;
71	  int ret = -1;
72	
73	  /* 读取配置文件 */
74	  fd = open(ROUTINE_CONFIG_PATH, O_RDONLY);
75	  if (fd < 0)
76	    {
77	      return send_json_error(client_fd, 404, "Config file not found");
78	    }
79	
80	  bytes_read = read(fd, buffer, sizeof(buffer) - 1);
81	  close(fd);
82	
83	  if (bytes_read <= 0)
84	    {
85	      return send_json_error(client_fd, 500, "Failed to read config");
86	    }
87	
88	  buffer[bytes_read] = '\0';
89	
90	  /* 解析 JSON */
91	  root = cJSON_Parse(buffer);
92	  if (root == NULL)
93	    {
94	      return send_json_error(client_fd, 500, "Invalid JSON");
95	    }
96	
97	  /* 提取语音相关配置 */
98	  voice_config = cJSON_CreateObject();
99	  if (voice_config == NULL)
100	    {
101	      cJSON_Delete(root);
102	      return send_json_error(client_fd, 500, "Memory allocation failed");
103	    }
104	
105	  /* 读取语音模式 */
106	  cJSON *voice_mode = cJSON_GetObjectItemCaseSensitive(root, "voice_mode");
107	  if (voice_mode && cJSON_IsString(voice_mode))
108	    {
109	      cJSON_AddStringToObject(voice_config, "voice_mode", voice_mode->valuestring);
110	    }
111	  else
112	    {
113	      cJSON_AddStringToObject(voice_config, "voice_mode", "offline");
114	    }
115	
116	  /* 读取 MiMo 配置 */
117	  cJSON *mimo_enabled = cJSON_GetObjectItemCaseSensitive(root, "mimo_enabled");
118	  cJSON_AddBoolToObject(voice_config, "mimo_enabled",
119	                        mimo_enabled && cJSON_IsTrue(mimo_enabled));
120	
121	  cJSON *mimo_model = cJSON_GetObjectItemCaseSensitive(root, "mimo_model");
122	  if (mimo_model && cJSON_IsString(mimo_model))
123	    {
124	      cJSON_AddStringToObject(voice_config, "mimo_model", mimo_model->valuestring);
125	    }
126	  else
127	    {
128	      cJSON_AddStringToObject(voice_config, "mimo_model", "mimo-v2.5");
129	    }
130	
131	  cJSON *mimo_tts_voice = cJSON_GetObjectItemCaseSensitive(root, "mimo_tts_voice");
132	  if (mimo_tts_voice && cJSON_IsString(mimo_tts_voice))
133	    {
134	      cJSON_AddStringToObject(voice_config, "mimo_tts_voice", mimo_tts_voice->valuestring);
135	    }
136	  else
137	    {
138	      cJSON_AddStringToObject(voice_config, "mimo_tts_voice", "冰糖");
139	    }
140	
141	  /* 读取 TTS 风格 */
142	  cJSON *mimo_tts_style = cJSON_GetObjectItemCaseSensitive(root, "mimo_tts_style");
143	  if (mimo_tts_style && cJSON_IsString(mimo_tts_style))
144	    {
145	      cJSON_AddStringToObject(voice_config, "mimo_tts_style", mimo_tts_style->valuestring);
146	    }
147	  else
148	    {
149	      cJSON_AddStringToObject(voice_config, "mimo_tts_style", "");
150	    }
151	
152	  /* API Key 只返回是否已配置，不返回实际值（安全考虑） */
153	  cJSON *mimo_api_key = cJSON_GetObjectItemCaseSensitive(root, "mimo_api_key");
154	  bool has_api_key = mimo_api_key && cJSON_IsString(mimo_api_key) &&
155	                     strlen(mimo_api_key->valuestring) > 0;
156	  cJSON_AddBoolToObject(voice_config, "has_api_key", has_api_key);
157	
158	  /* 生成响应 */
159	  response_json = cJSON_PrintUnformatted(voice_config);
160	  if (response_json)
161	    {
162	      ret = send_response(client_fd, 200, "OK", "application/json", response_json);
163	      free(response_json);
164	    }
165	  else
166	    {
167	      ret = send_json_error(client_fd, 500, "Failed to generate JSON");
168	    }
169	
170	  cJSON_Delete(voice_config);
171	  cJSON_Delete(root);
172	  return ret;
173	}
