55	static int send_json_error(int fd, int status_code, const char *message)
56	{
57	  char body[256];
58	  snprintf(body, sizeof(body), "{\"error\":\"%s\"}", message);
59	  return send_response(fd, status_code, "Error", "application/json", body);
60	}
