77	    {
78	      /* 配置文件不存在，使用默认值 */
79	      use_defaults = true;
80	    }
81	  else
82	    {
83	      bytes_read = read(fd, buffer, sizeof(buffer) - 1);
84	      close(fd);
85	
86	      if (bytes_read <= 0)
87	        {
88	          use_defaults = true;
89	        }
90	      else
91	        {
92	          buffer[bytes_read] = '\0';
