136	
137	  if (!use_defaults && root != NULL)
138	    {
139	      mimo_enabled = cJSON_GetObjectItemCaseSensitive(root, "mimo_enabled");
140	      mimo_model = cJSON_GetObjectItemCaseSensitive(root, "mimo_model");
