144	    }
145	
146	  cJSON_AddBoolToObject(voice_config, "mimo_enabled",
147	                        mimo_enabled && cJSON_IsTrue(mimo_enabled));
148	
149	  if (mimo_model && cJSON_IsString(mimo_model))
150	    {
151	      cJSON_AddStringToObject(voice_config, "mimo_model", mimo_model->valuestring);
152	    }
153	  else
154	    {
155	      cJSON_AddStringToObject(voice_config, "mimo_model", "mimo-v2.6");
156	    }
157	
158	  if (mimo_tts_voice && cJSON_IsString(mimo_tts_voice))
159	    {

155	      cJSON_AddStringToObject(voice_config, "mimo_model", "mimo-v2.6");
156	    }
157	
158	  if (mimo_tts_voice && cJSON_IsString(mimo_tts_voice))
