          /* 1.5秒后恢复按钮颜色并清除提示 */
          lv_timer_create(routine_voice_mode_error_timer_cb, 1500, NULL);

          return;
        }
    }

  /* 切换在线/离线模式 */
  g_ui.voice_online_mode = !g_ui.voice_online_mode;

